#!/usr/bin/env node
// sync-claude-md.mjs
// ---------------------------------------------------------------------------
// Mirrors the canonical root `AGENTS.md` into a root `CLAUDE.md` so Claude Code
// picks up the same conventions. Codex and most other agents read `AGENTS.md`
// directly; Claude Code reads `CLAUDE.md`. Rather than maintain two documents,
// `AGENTS.md` is canonical and `CLAUDE.md` is generated from it and carries a
// "do not edit" banner — the same pattern used for skills by
// `.agents/skills/sync-to-claude.mjs`.
//
// Usage:
//   node .agents/scripts/sync-claude-md.mjs           # write/refresh CLAUDE.md
//   node .agents/scripts/sync-claude-md.mjs --check     # verify only, no writes
//   node .agents/scripts/sync-claude-md.mjs --help
//
// Exit codes:
//   0  success (write mode), or mirror already in sync (--check)
//   1  mirror is stale or missing (--check), or an error occurred
// ---------------------------------------------------------------------------

import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..", ".."); // .agents/scripts -> repo root
const SRC = path.join(REPO_ROOT, "AGENTS.md");
const DEST = path.join(REPO_ROOT, "CLAUDE.md");

const args = new Set(process.argv.slice(2));
const CHECK = args.has("--check");
if (args.has("--help") || args.has("-h")) {
  console.log(
    [
      "Mirror root AGENTS.md -> root CLAUDE.md (Claude Code discovery).",
      "",
      "  --check   verify CLAUDE.md is current; exit 1 if stale/missing (no writes)",
      "  --help    show this message",
    ].join("\n"),
  );
  process.exit(0);
}

const stripBom = (s) => s.replace(/^﻿/, "");

const BANNER = [
  "<!--",
  "  MIRROR — do not edit here.",
  "  Canonical source: AGENTS.md (repo root).",
  "  Generated by .agents/scripts/sync-claude-md.mjs. Claude Code reads CLAUDE.md;",
  "  Codex and most other agents read AGENTS.md. Edit AGENTS.md, then re-run the",
  "  sync tool: node .agents/scripts/sync-claude-md.mjs",
  "-->",
  "",
  "",
].join("\n");

/** Desired CLAUDE.md content: the banner followed by the canonical AGENTS.md. */
function desired(agentsContent) {
  return BANNER + stripBom(agentsContent);
}

async function readMaybe(file) {
  try {
    return await fs.readFile(file, "utf8");
  } catch {
    return null;
  }
}

async function main() {
  const src = await readMaybe(SRC);
  if (src === null) {
    console.error(`Canonical source not found: ${path.relative(REPO_ROOT, SRC)}`);
    process.exit(1);
  }

  const want = desired(src);
  const have = await readMaybe(DEST);
  const norm = (t) => t.replace(/\r\n/g, "\n");
  const inSync = have !== null && norm(have) === norm(want);

  if (CHECK) {
    if (inSync) {
      console.log("CLAUDE.md is in sync with AGENTS.md.");
      return;
    }
    console.error(
      have === null
        ? "CLAUDE.md is MISSING."
        : "CLAUDE.md is OUT OF SYNC with AGENTS.md.",
    );
    console.error("\nRun: node .agents/scripts/sync-claude-md.mjs");
    process.exit(1);
  }

  if (inSync) {
    console.log("Already in sync; nothing to write.");
    return;
  }
  await fs.writeFile(DEST, want, "utf8");
  console.log(`Wrote ${path.relative(REPO_ROOT, DEST)} from AGENTS.md.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
